RACE_X["race-a5"]=Object.assign(RACE_X["race-a5"]||{},{cs:["using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n\n        bool nt = n >= 2;\n        for (long d = 2; d < n; d++)\n        {\n            if (n % d == 0)\n            {\n                nt = false;\n                break;\n            }\n        }\n        Console.WriteLine(nt ? \"nguyen to\" : \"hop so\");\n    }\n}", "using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n\n        bool nt = n >= 2;\n        for (long d = 2; d * d <= n; d++)\n        {\n            if (n % d == 0)\n            {\n                nt = false;\n                break;\n            }\n        }\n        Console.WriteLine(nt ? \"nguyen to\" : \"hop so\");\n    }\n}"]});
