const PR5=[{label:"Ví dụ: Kiểm tra nguyên tố O(n)",input:"100003",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    bool nt = n >= 2;\n    for (long long d = 2; d < n; d++) {\n        if (n % d == 0) {\n            nt = false;\n            break;\n        }\n    }\n    cout << (nt ? \"nguyen to\" : \"hop so\") << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","d","nt"]}],py:{code:"n = int(input())\nnt = n >= 2\nfor d in range(2, n):\n    if n % d == 0:\n        nt = False\n        break\nprint(\"nguyen to\" if nt else \"hop so\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n\n        bool nt = n >= 2;\n        for (long d = 2; d < n; d++)\n        {\n            if (n % d == 0)\n            {\n                nt = false;\n                break;\n            }\n        }\n        Console.WriteLine(nt ? \"nguyen to\" : \"hop so\");\n    }\n}"}},{label:"Ví dụ: Kiểm tra nguyên tố O(√n)",input:"100003",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    bool nt = n >= 2;\n    for (long long d = 2; d * d <= n; d++) {\n        if (n % d == 0) {\n            nt = false;\n            break;\n        }\n    }\n    cout << (nt ? \"nguyen to\" : \"hop so\") << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","d","nt"]}],py:{code:"n = int(input())\nnt = n >= 2\nd = 2\nwhile d * d <= n:\n    if n % d == 0:\n        nt = False\n        break\n    d += 1\nprint(\"nguyen to\" if nt else \"hop so\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n\n        bool nt = n >= 2;\n        for (long d = 2; d * d <= n; d++)\n        {\n            if (n % d == 0)\n            {\n                nt = false;\n                break;\n            }\n        }\n        Console.WriteLine(nt ? \"nguyen to\" : \"hop so\");\n    }\n}"}},{label:"Ví dụ: Liệt kê ước theo cặp",input:"36",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    for (long long d = 1; d * d <= n; d++) {\n        if (n % d == 0) {\n            cout << d;\n            if (d != n / d) cout << \" \" << n / d;\n            cout << \"\\n\";\n        }\n    }\n    return 0;\n}",viz:[{type:"vars",names:["n","d"]}],py:{code:"n = int(input())\nd = 1\nwhile d * d <= n:\n    if n % d == 0:\n        if d != n // d:\n            print(d, n // d)\n        else:\n            print(d)\n    d += 1"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n\n        for (long d = 1; d * d <= n; d++)\n        {\n            if (n % d == 0)\n            {\n                Console.Write(d);\n                if (d != n / d) Console.Write(\" \" + n / d);\n                Console.WriteLine();\n            }\n        }\n    }\n}"}},{label:"Ví dụ: Quy tắc cộng và nhân",input:"16",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    long long a = 0, b = 0;\n    for (int i = 0; i < n; i++) a++;                 // O(n)\n    for (int i = 0; i < n; i++)\n        for (int j = 1; j < n; j *= 2) b++;          // O(n log n)\n    cout << a << \" \" << b << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","i","j","a","b"]}],py:{code:"n = int(input())\na = 0\nb = 0\nfor i in range(n):          # O(n)\n    a += 1\nfor i in range(n):          # O(n log n)\n    j = 1\n    while j < n:\n        b += 1\n        j *= 2\nprint(a, b)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long a = 0, b = 0;\n        for (int i = 0; i < n; i++) a++;                 // O(n)\n        for (int i = 0; i < n; i++)\n            for (int j = 1; j < n; j *= 2) b++;          // O(n log n)\n        Console.WriteLine(a + \" \" + b);\n    }\n}"}}];
